import { useState, type FormEvent } from "react"

import {
  DANGER_BUTTON,
  FormField,
  INPUT_CLASS,
  IssueList,
  NotFoundPanel,
  PageHeading,
  PRIMARY_BUTTON,
  Panel,
  SECONDARY_BUTTON,
  issueMessages,
} from "./shared"
import type { ScreenProps } from "./types"

interface PackValues {
  title: string
  titleZh: string
}

/**
 * The pack editor. A pack is created under one topic and never moves, so the
 * topic is read-only here; the id is generated by the server.
 */
export function PackForm({
  route,
  snapshot,
  api,
  navigate,
  refresh,
  notify,
  report,
}: ScreenProps) {
  const packId = route.screen === "pack" ? route.packId : null
  const newTopicId = route.screen === "packNew" ? route.topicId : null
  const existing =
    packId === null
      ? undefined
      : snapshot.packs.find((pack) => pack.id === packId)
  const topicId = existing?.topicId ?? newTopicId
  const topic =
    topicId === null || topicId === undefined
      ? undefined
      : snapshot.topics.find((candidate) => candidate.id === topicId)

  const [values, setValues] = useState<PackValues>(() => ({
    title: existing?.title ?? "",
    titleZh: existing?.titleZh ?? "",
  }))
  const [issues, setIssues] = useState<string[]>([])
  const [busy, setBusy] = useState(false)

  if (packId !== null && existing === undefined) {
    return <NotFoundPanel message="That pack does not exist." />
  }

  if (topic === undefined) {
    return <NotFoundPanel message="The pack's topic does not exist." />
  }

  const back = { screen: "packs", topicId: topic.id } as const

  if (
    topic.archivedAt !== null ||
    (existing !== undefined && existing.archivedAt !== null)
  ) {
    return (
      <Panel>
        <p className="text-sm font-bold">This pack is archived.</p>
        <p className="mt-1 text-xs text-[var(--admin-muted)]">
          Restore it from the Archived view before editing.
        </p>
        <button
          type="button"
          className={`${SECONDARY_BUTTON} mt-4`}
          onClick={() => navigate({ screen: "archived", tab: "packs" })}
        >
          Open Archived
        </button>
      </Panel>
    )
  }

  async function save(event: FormEvent<HTMLFormElement>): Promise<void> {
    event.preventDefault()
    setBusy(true)
    setIssues([])

    try {
      const result =
        existing === undefined
          ? await api.createPack(
              { topicId: topic!.id, ...values },
              snapshot.contentVersion,
            )
          : await api.updatePack(
              existing.id,
              values,
              snapshot.contentVersion,
            )

      await refresh()
      notify(
        result.warnings.length === 0
          ? existing === undefined
            ? "Pack created."
            : "Pack saved."
          : `Saved with ${result.warnings.length} editorial ${
              result.warnings.length === 1 ? "warning" : "warnings"
            }.`,
      )
      navigate(back)
    } catch (caught) {
      setIssues(issueMessages(caught))
      report(caught)
    } finally {
      setBusy(false)
    }
  }

  async function archive(): Promise<void> {
    if (existing === undefined) return

    const confirmed = window.confirm(
      `Archive “${existing.title}”? It is hidden from children. The words stay in the word library.`,
    )
    if (!confirmed) return

    setBusy(true)

    try {
      await api.setPackArchived(existing.id, true, snapshot.contentVersion)
      await refresh()
      notify("Pack archived.")
      navigate(back)
    } catch (caught) {
      report(caught)
    } finally {
      setBusy(false)
    }
  }

  return (
    <>
      <PageHeading
        title={existing === undefined ? "New pack" : "Edit pack"}
        description={`In ${topic.title} · ${topic.titleZh}`}
      />

      <IssueList issues={issues} />

      <form onSubmit={(event) => void save(event)} className="grid gap-5">
        <Panel>
          <div className="grid gap-4 sm:grid-cols-2">
            <FormField label="English title">
              <input
                className={INPUT_CLASS}
                required
                value={values.title}
                onChange={(event) =>
                  setValues((current) => ({
                    ...current,
                    title: event.target.value,
                  }))
                }
                placeholder="My Workshop"
              />
            </FormField>
            <FormField label="Chinese title">
              <input
                className={INPUT_CLASS}
                required
                value={values.titleZh}
                onChange={(event) =>
                  setValues((current) => ({
                    ...current,
                    titleZh: event.target.value,
                  }))
                }
                placeholder="我的工坊"
              />
            </FormField>
            <FormField
              label="Topic"
              hint="A pack cannot move to another topic."
            >
              <input className={INPUT_CLASS} readOnly value={topic.title} />
            </FormField>
            {existing === undefined ? null : (
              <FormField label="Id" hint="Generated once and never reused.">
                <input className={INPUT_CLASS} readOnly value={existing.id} />
              </FormField>
            )}
          </div>
        </Panel>

        <div className="flex flex-wrap items-center gap-3">
          <button type="submit" className={PRIMARY_BUTTON} disabled={busy}>
            {busy ? "Saving…" : "Save"}
          </button>
          <button
            type="button"
            className={SECONDARY_BUTTON}
            onClick={() => navigate(back)}
          >
            Cancel
          </button>
        </div>
      </form>

      {existing === undefined ? null : (
        <div className="mt-8 rounded-[15px] border border-[var(--admin-coral)]/25 bg-white p-5">
          <h2 className="text-sm font-extrabold text-[var(--admin-coral)]">
            Danger zone
          </h2>
          <p className="mt-1 max-w-[640px] text-xs text-[var(--admin-muted)]">
            Archived packs are hidden from children. The words stay in the word
            library.
          </p>
          <button
            type="button"
            className={`${DANGER_BUTTON} mt-4`}
            disabled={busy}
            onClick={() => void archive()}
          >
            Archive pack
          </button>
        </div>
      )}
    </>
  )
}
